# Build a single-file Windows exe with PyInstaller (pip install pyinstaller first).
# The icon is generated by tools/make_icon.py (run it again after changing the design).
$ErrorActionPreference = "Stop"
Set-Location $PSScriptRoot
python -m PyInstaller --noconfirm --clean --onefile --windowed --name PicoCompanion `
    --icon assets/icon.ico --add-data "assets/icon.ico;assets" pico_companion.py
Write-Host "Built: $PSScriptRoot\dist\PicoCompanion.exe"
